pub(crate) fn same_sources(&self, other: &Self) -> bool {
    match (&self.data, &other.data) {
        (Data::Bytes(a), Data::Bytes(b)) => a == b,
        (Data::Repeatable(a), Data::Repeatable(b)) => Arc::ptr_eq(a, b),
        (Data::Concat(a), Data::Concat(b)) => {
            a.len() == b.len() && a.iter().zip(b).all(|(a, b)| a.same_sources(b))
        }
        (Data::Map(a, am), Data::Map(b, bm)) => Arc::ptr_eq(am, bm) && a.same_sources(b),
        _ => false,
    }
}
